BEGIN;
DO $p$ DECLARE d text; d0 text; g text := $x$coalesce((e.manifest->>'governed_repair_write')::boolean,false)$x$; BEGIN d := pg_get_functiondef('public.lf_profile_native_bridge_prepare_v1(text,text,text,text)'::regprocedure); d0 := d; d := regexp_replace(d, $r$case when jsonb_array_length\(v_skill_findings\)>0\s+then 'READ_ONLY_WITH_IG_FINDINGS' else 'READ_ONLY_PROFILE_VALIDATION' end$r$, 'case when '||g||' then ''GOVERNED_REPAIR'' when jsonb_array_length(v_skill_findings)>0 then ''READ_ONLY_WITH_IG_FINDINGS'' else ''READ_ONLY_PROFILE_VALIDATION'' end', 'g'); d := regexp_replace(d, $r$'mutation_authorized',false,(\s+)'allowed_actions'$r$, '''mutation_authorized'','||g||',\1''allowed_actions'''); IF d = d0 OR position('GOVERNED_REPAIR' in d)=0 OR position('mutation_authorized'','||g in d)=0 THEN RAISE EXCEPTION 'LF_STEP40_PATCH_A_NOT_APPLIED'; END IF; EXECUTE d; d := pg_get_functiondef('public.lf_profile_native_bridge_record_report_v1(text,text,text)'::regprocedure); d0 := d; d := replace(d, $s$v_input->>'analysis_scope' IS DISTINCT FROM 'READ_ONLY_WITH_IG_FINDINGS'$s$, $s$coalesce(v_input->>'analysis_scope','') NOT IN ('READ_ONLY_WITH_IG_FINDINGS','GOVERNED_REPAIR')$s$); IF d = d0 THEN RAISE EXCEPTION 'LF_STEP40_PATCH_B_NOT_APPLIED'; END IF; EXECUTE d; END $p$;
